/**
 * Preserves leading '~' on OpenRouter ':latest' wire slugs (fixes fableforge tilde-stripping bug).
 */
export function normalizeOpenRouterWireModel(rawModelId: string): string {
  const trimmed = rawModelId.trim();
  if (!trimmed) return "~openai/gpt-mini-latest";
  if (LEGACY_MODEL_ALIASES_SNAPSHOT[trimmed]) return LEGACY_MODEL_ALIASES_SNAPSHOT[trimmed]!;
  const withoutTilde = trimmed.startsWith("~") ? trimmed.slice(1) : trimmed;
  if (LEGACY_MODEL_ALIASES_SNAPSHOT[withoutTilde]) return LEGACY_MODEL_ALIASES_SNAPSHOT[withoutTilde]!;
  const found = PLATFORM_MODELS_SNAPSHOT.find((m) => m.id === withoutTilde || m.wireModel === trimmed);
  if (found) return found.wireModel;
  if (trimmed.endsWith("-latest") && !trimmed.startsWith("~") && trimmed !== "openai/gpt-chat-latest") {
    return `~${trimmed}`;
  }
  return trimmed;
}

export function resolveVisualRoute(options: {
  surface: string;
  contentPolicy?: "sfw";
  contentRating?: "sfw" | "moderate";
  hasCharacterReferences?: boolean;
  referenceCount?: number;
}) {
  const base =
    VISUAL_SURFACE_ROUTES_SNAPSHOT.find((r) => r.surface === options.surface) ??
    VISUAL_SURFACE_ROUTES_SNAPSHOT[1]!;
  if (options.hasCharacterReferences && (options.referenceCount ?? 0) >= 1) {
    return {
      ...base,
      primaryModel: "google/gemini-3.1-flash-image",
      primaryGateway: "openrouter",
    };
  }
  return base;
}

export function assertVectorSpaceCompatible(sourceModelId: string, targetModelId: string) {
  const map = EMBEDDING_VECTOR_SPACES_SNAPSHOT as Readonly<
    Record<string, { modelId: string; revision: string; dimensions: number; normalizeL2: boolean }>
  >;
  const s = map[sourceModelId];
  const t = map[targetModelId];
  if (!s || !t) {
    return { compatible: false, reason: `Unknown embedding vector space for ${sourceModelId} or ${targetModelId}` };
  }
  if (s.dimensions !== t.dimensions) {
    return {
      compatible: false,
      reason: `Vector dimension mismatch: ${s.modelId} (${s.dimensions}d) vs ${t.modelId} (${t.dimensions}d).`,
    };
  }
  if (s.modelId !== t.modelId || s.revision !== t.revision) {
    return {
      compatible: false,
      reason: `Embedding space mismatch: ${s.modelId}@${s.revision} vs ${t.modelId}@${t.revision}.`,
    };
  }
  return { compatible: true, reason: `Verified compatible vector space ${s.modelId}@${s.revision} (${s.dimensions}d).` };
}

export function isDeepSeekOffPeakUtc(utcHour: number, utcMinute = 30): boolean {
  const totalMinutes = ((utcHour % 24) * 60) + (utcMinute % 60);
  return totalMinutes >= 16 * 60 + 30 || totalMinutes <= 30;
}

export function wilsonScoreLowerBound(successes: number, total: number, z = 1.96): number {
  if (total <= 0) return 0;
  const phat = Math.max(0, Math.min(1, successes / total));
  const z2 = z * z;
  const denom = 1 + z2 / total;
  const center = phat + z2 / (2 * total);
  const spread = z * Math.sqrt((phat * (1 - phat) + z2 / (4 * total)) / total);
  return Number(Math.max(0, Math.min(1, (center - spread) / denom)).toFixed(4));
}

export function usdToNano(usd: number): number {
  return Math.round(usd * NANO_USD_PER_USD);
}

export function nanoToUsd(nanoUsd: number): number {
  return Number((nanoUsd / NANO_USD_PER_USD).toFixed(6));
}

export function computeStalenessHorizon(docPath: string, baseHorizonDays = 90) {
  let h = 0x811c9dc5;
  const s = (docPath || "").trim().toLowerCase();
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  const jitterDays = ((h >>> 0) % 15) - 7;
  return {
    baseHorizonDays,
    jitterDays,
    effectiveHorizonDays: Math.max(7, baseHorizonDays + jitterDays),
  };
}

export function evaluateSearchCircuitBreaker(
  consecutiveFailures: number,
  baseDelaySec = 15,
  failureThreshold = 3,
) {
  const failures = Math.max(0, Math.floor(consecutiveFailures));
  const state = failures >= failureThreshold ? "open" : failures > 0 ? "half_open" : "closed";
  const cooldownSec = failures === 0 ? 0 : baseDelaySec * Math.pow(2, Math.min(failures, 4));
  return {
    state,
    consecutiveFailures: failures,
    cooldownSec,
    shouldSkipProvider: state === "open",
  };
}

export function evaluateBeforeAfterCvFlywheel(input: {
  beforeCv: {
    edgeSharpness: number;
    luminanceContrast: number;
    noiseFloor: number;
    vlmRubric: {
      technicalQuality: number;
      promptAdherence: number;
      anatomicalAccuracy: number;
      compositionQuality: number;
      styleConsistency: number;
    };
  };
  afterCv: {
    edgeSharpness: number;
    luminanceContrast: number;
    noiseFloor: number;
    vlmRubric: {
      technicalQuality: number;
      promptAdherence: number;
      anatomicalAccuracy: number;
      compositionQuality: number;
      styleConsistency: number;
    };
  };
  afterGrounded?: boolean;
}) {
  const score = (r: {
    technicalQuality: number;
    promptAdherence: number;
    anatomicalAccuracy: number;
    compositionQuality: number;
    styleConsistency: number;
  }) =>
    Number(
      (
        0.25 * r.technicalQuality +
        0.3 * r.promptAdherence +
        0.2 * r.anatomicalAccuracy +
        0.15 * r.compositionQuality +
        0.1 * r.styleConsistency
      ).toFixed(4),
    );
  const visualBeforeScore = score(input.beforeCv.vlmRubric);
  const visualAfterScore = score(input.afterCv.vlmRubric);
  const visualDelta = Number((visualAfterScore - visualBeforeScore).toFixed(4));
  const edgeSharpnessDeltaPct = Number(
    (
      ((input.afterCv.edgeSharpness - input.beforeCv.edgeSharpness) /
        Math.max(1, input.beforeCv.edgeSharpness)) *
      100
    ).toFixed(1),
  );
  const contrastDeltaPct = Number(
    (
      ((input.afterCv.luminanceContrast - input.beforeCv.luminanceContrast) /
        Math.max(1, input.beforeCv.luminanceContrast)) *
      100
    ).toFixed(1),
  );
  const noiseReductionPct = Number(
    (
      ((input.beforeCv.noiseFloor - input.afterCv.noiseFloor) /
        Math.max(1, input.beforeCv.noiseFloor)) *
      100
    ).toFixed(1),
  );
  const estimatedPsnrDb = Number(
    (28 + visualAfterScore * 11 + Math.max(0, noiseReductionPct) * 0.08).toFixed(2),
  );
  const flywheelConverged =
    visualAfterScore >= 0.74 &&
    input.afterCv.vlmRubric.anatomicalAccuracy >= 0.6 &&
    (input.afterGrounded ?? true) &&
    visualDelta >= 0;
  return {
    visualBeforeScore,
    visualAfterScore,
    visualDelta,
    edgeSharpnessDeltaPct,
    contrastDeltaPct,
    noiseReductionPct,
    estimatedPsnrDb,
    flywheelConverged,
  };
}

export function selectModelForTask(
  taskTier: string,
  grossMarginPct = 0.65,
  isGuest = false,
) {
  if (isGuest || grossMarginPct < 0.35) {
    return {
      wireModel: "~openai/gpt-mini-latest",
      enforcedTier: "free_or_local",
      downgradedByGuard: true,
    };
  }
  if (taskTier === "frontier_reasoning") {
    return {
      wireModel: "~anthropic/claude-opus-latest",
      enforcedTier: "frontier_reasoning",
      downgradedByGuard: false,
    };
  }
  if (taskTier === "balanced_production") {
    return {
      wireModel: "~anthropic/claude-sonnet-latest",
      enforcedTier: "balanced_production",
      downgradedByGuard: false,
    };
  }
  return {
    wireModel: "~openai/gpt-mini-latest",
    enforcedTier: "free_or_local",
    downgradedByGuard: false,
  };
}

export function reciprocalRankFusion(
  denseRank: number,
  lexicalRank: number,
  k = 60,
  temporalBonus = 0.0,
): number {
  const d = Math.max(1, Math.floor(denseRank));
  const l = Math.max(1, Math.floor(lexicalRank));
  const kk = Math.max(1, Math.floor(k));
  const score = 1.0 / (kk + d) + 1.0 / (kk + l) + temporalBonus;
  return Number(score.toFixed(6));
}

export function evaluateHallucinationGate(
  evidenceQuality: number,
  citationCoverage: number,
  normalizedLogprob: number,
  semanticEntropyInverse: number,
  selfConsistency: number,
) {
  const confidence = Number(
    (
      0.15 * evidenceQuality +
      0.15 * citationCoverage +
      0.3 * normalizedLogprob +
      0.2 * semanticEntropyInverse +
      0.2 * selfConsistency
    ).toFixed(4),
  );
  const action =
    confidence >= 0.78
      ? "answer"
      : confidence >= 0.58
        ? "hedge_with_citations"
        : confidence >= 0.38
          ? "clarify"
          : "abstain";
  return { confidence, action };
}

export function enforceFleetProfitabilityGuard(
  grossRevenueNano: number,
  llmSpendNano: number,
  infraSpendNano: number,
  isGuest = false,
) {
  const netProfitNano = Math.round(grossRevenueNano - llmSpendNano - infraSpendNano);
  const denom = Math.max(1, grossRevenueNano);
  const netMarginPct = Number(((netProfitNano / denom) * 100.0).toFixed(2));
  if (isGuest) {
    return {
      netProfitNano,
      netMarginPct,
      enforcedTier: "free_or_local",
      reason: "guest_sybil_cloud_spend_block",
    };
  }
  if (netMarginPct < 35.0) {
    return {
      netProfitNano,
      netMarginPct,
      enforcedTier: "free_or_local",
      reason: "margin_leak_enact_cost_lever",
    };
  }
  return {
    netProfitNano,
    netMarginPct,
    enforcedTier: "balanced_production",
    reason: "healthy_margin_floor",
  };
}

export function evaluateWcagContrastRatio(fgLuminance: number, bgLuminance: number) {
  const lighter = Math.max(0, Math.max(fgLuminance, bgLuminance));
  const darker = Math.max(0, Math.min(fgLuminance, bgLuminance));
  const contrastRatio = Number(((lighter + 0.05) / (darker + 0.05)).toFixed(2));
  return {
    contrastRatio,
    passesAa: contrastRatio >= 4.5,
    passesAaa: contrastRatio >= 7.0,
  };
}

export function evaluateFleetHealthAndFocus(
  activeUsers: number,
  netMarginPct: number,
  errorRatePct: number,
) {
  if (errorRatePct > 2.0) {
    return { quadrant: "reliability_incident_mitigation", healthy: false };
  }
  if (netMarginPct < 35.0) {
    return { quadrant: "margin_leak_enact_cost_lever", healthy: false };
  }
  if (activeUsers >= 100 && netMarginPct >= 50.0) {
    return { quadrant: "scale_winner_invest_growth", healthy: true };
  }
  return { quadrant: "steady_maintenance_observability", healthy: true };
}

export function stepForceDirectedLayout(
  dx: number,
  dy: number,
  idealDist = 120.0,
  damping = 0.85,
) {
  const dist = Math.max(1.0, Math.sqrt(dx * dx + dy * dy));
  const force = (dist - idealDist) * 0.05;
  const vx = Number(((dx / dist) * force * damping).toFixed(4));
  const vy = Number(((dy / dist) * force * damping).toFixed(4));
  return { vx, vy, distance: Number(dist.toFixed(4)) };
}
